#[test]
fn doctor_flags_a_stale_generated_file() {
    let tree = TempTree::new("doctor-stale");
    tree.write_config(SAMPLE_ALL_USED);
    cloakroom(&tree, &tree.home(), &["init"]);
    let root = tree.config_dir().join("generated/root.gitconfig");
    let mut contents = std::fs::read_to_string(&root).unwrap();
    contents.push_str("# hand edit\n");
    std::fs::write(&root, contents).unwrap();

    let output = cloakroom(&tree, &tree.home(), &["doctor"]);
    assert_eq!(code(&output), 1, "stdout: {}", stdout(&output));
    assert!(stdout(&output).contains("generated/root.gitconfig is stale"));
}

