/// An empty config in a sandbox with no system or global identity. Nothing
/// is broken; git has no name or email here, and doctor says so
/// because git will refuse the next commit.
#[test]
fn doctor_reports_missing_identity_fields() {
    let tree = TempTree::new("doctor-missing-identity");
    tree.write_config("");
    cloakroom(&tree, &tree.home(), &["init"]);
    let repo = repo(&tree, "missing-identity/app");

    let output = cloakroom(&tree, &repo, &["doctor"]);
    let report = stdout(&output);
    assert_eq!(code(&output), 1, "stdout: {report}");
    assert!(report.contains("no user.name resolves"));
    assert!(report.contains("no user.email resolves"));
}

#[test]
fn doctor_accepts_a_complete_identity_when_no_rule_matches() {
    let tree = TempTree::new("doctor-foreign-identity");
    tree.write_config("");
    cloakroom(&tree, &tree.home(), &["init"]);
    git(
        &tree,
        &tree.home(),
        &["config", "--global", "user.name", "Pat Global"],
    );
    git(
        &tree,
        &tree.home(),
        &["config", "--global", "user.email", "pat@global.example"],
    );
    let repo = repo(&tree, "foreign-identity/app");

    let output = cloakroom(&tree, &repo, &["doctor"]);
    assert_eq!(code(&output), 0, "stdout: {}", stdout(&output));
    assert!(stdout(&output).contains("identity comes from elsewhere"));
}

#[test]
fn doctor_rejects_an_external_profile_marker() {
    let tree = TempTree::new("doctor-marker");
    tree.write_config(SAMPLE_ALL_USED);
    cloakroom(&tree, &tree.home(), &["init"]);
    let repo = repo(&tree, "src/work/app");
    git(&tree, &repo, &["config", "cloakroom.profile", "work"]);
    git(&tree, &repo, &["config", "user.name", "Pat Work"]);
    git(&tree, &repo, &["config", "user.email", "pat@work.example"]);

    let output = cloakroom(&tree, &repo, &["doctor"]);
    assert_eq!(code(&output), 1, "stdout: {}", stdout(&output));
    assert!(stdout(&output).contains("not a generated object"));
}

/// The config is rewritten after apply, so the generated files still select
/// work while config.toml no longer defines it. The marker is genuine and the
/// identity is real; only the source has moved on.
#[test]
fn doctor_flags_a_generated_marker_missing_from_the_source() {
    let tree = TempTree::new("doctor-unknown-marker");
    tree.write_config(SAMPLE_ALL_USED);
    cloakroom(&tree, &tree.home(), &["init"]);
    let repo = repo(&tree, "src/work/app");
    tree.write_config(
        "[profiles.personal]\nname = \"Pat Personal\"\nemail = \"pat@example.com\"\n\
         [[rules]]\nprofile = \"personal\"\npath = \"~/src/work/\"\n",
    );

    let output = cloakroom(&tree, &repo, &["doctor"]);
    assert_eq!(code(&output), 1, "stdout: {}", stdout(&output));
    assert!(stdout(&output).contains("profile marker \"work\" is not in config.toml"));
}

/// A broken config does not stop the already generated files from selecting
/// an identity. Doctor has to keep going and report, not stop at the config.
#[test]
fn doctor_still_checks_a_selected_identity_when_the_config_is_invalid() {
    let tree = TempTree::new("doctor-invalid-selected");
    tree.write_config(SAMPLE_ALL_USED);
    cloakroom(&tree, &tree.home(), &["init"]);
    let repo = repo(&tree, "src/work/invalid-source");
    tree.write_config("[[rules]]\nprofile = \"missing\"\npath = \"~/src/\"\n");

    let output = cloakroom(&tree, &repo, &["doctor"]);
    assert_eq!(code(&output), 1, "stdout: {}", stdout(&output));
    assert!(stdout(&output).contains("unknown profile"));
}

/// The publish order under failure. A directory is created where the new
/// object file has to go, which makes that write fail with the config already
/// validated. The root must still be the previous one, because a root naming
/// an object that does not exist is a gitconfig git cannot read.
#[test]
fn apply_keeps_the_previous_root_when_an_object_write_fails() {
    let tree = TempTree::new("publish-failure");
    tree.write_config(SAMPLE);
    let output = cloakroom(&tree, &tree.home(), &["apply"]);
    assert_eq!(code(&output), 0, "stderr: {}", stderr(&output));
    let root_before = tree.read_generated("root.gitconfig");

    let changed = SAMPLE.replace("name = \"Pat Work\"", "name = \"New Work\"");
    tree.write_config(&changed);
    let changed_object = GOLDEN_WORK_PROFILE.replace("Pat Work", "New Work");
    let blocked = tree
        .config_dir()
        .join("generated/objects")
        .join(format!("{}.gitconfig", digest(&changed_object)));
    std::fs::create_dir(&blocked).unwrap();

    let output = cloakroom(&tree, &tree.home(), &["apply"]);
    assert_eq!(code(&output), 2, "stdout: {}", stdout(&output));
    assert_eq!(tree.read_generated("root.gitconfig"), root_before);
}

