/// Why the marker exists. Two profiles share an email, so the identity alone
/// cannot say which rule matched, and status still names b.
#[test]
fn profile_marker_distinguishes_profiles_that_share_an_email() {
    let tree = TempTree::new("shared-email");
    tree.write_config(
        "[profiles.a]\nname = \"A\"\nemail = \"same@example.com\"\n\
         [profiles.b]\nname = \"B\"\nemail = \"same@example.com\"\n\
         [[rules]]\nprofile = \"a\"\npath = \"~/src/a/\"\n\
         [[rules]]\nprofile = \"b\"\npath = \"~/src/b/\"\n",
    );
    cloakroom(&tree, &tree.home(), &["init"]);
    let repo = repo(&tree, "src/b/app");

    let output = cloakroom(&tree, &repo, &["status"]);
    assert_eq!(code(&output), 0, "stderr: {}", stderr(&output));
    let report = stdout(&output);
    assert!(
        report.contains("identity:   B <same@example.com>"),
        "{report}"
    );
    assert!(
        report.contains("profile:    b (selected by cloakroom)"),
        "{report}"
    );
}

