/// Two files dropped into objects/: a stray gitconfig, which is reported
/// because it is a [user] block an old root could still include, and a
/// README, which is not cloakroom's to judge and must be left alone.
#[test]
fn doctor_flags_an_unreferenced_object() {
    let tree = TempTree::new("doctor-object");
    tree.write_config(SAMPLE_ALL_USED);
    cloakroom(&tree, &tree.home(), &["init"]);
    std::fs::write(
        tree.config_dir().join("generated/objects/unused.gitconfig"),
        "",
    )
    .unwrap();
    std::fs::write(tree.config_dir().join("generated/objects/README"), "").unwrap();

    let output = cloakroom(&tree, &tree.home(), &["doctor"]);
    assert_eq!(code(&output), 1, "stdout: {}", stdout(&output));
    assert!(stdout(&output).contains("not in the current manifest"));
}

/// A valueless key anywhere in the user's gitconfig used to abort every
/// report, because cloakroom reads one `git config --list` for all of them.
/// The key is unrelated to the identity, so the identity must still resolve.
#[test]
fn reports_survive_a_valueless_key_in_the_gitconfig() {
    let tree = TempTree::new("valueless-key");
    tree.write_config(SAMPLE_ALL_USED);
    cloakroom(&tree, &tree.home(), &["init"]);
    let repo = repo(&tree, "src/work/app");
    // git config refuses to write a valueless key, so the global gitconfig
    // is replaced by hand. The include init added goes back in with it.
    std::fs::write(
        tree.home().join(".gitconfig"),
        format!(
            "[pull]\n\trebase\n[include]\n\tpath = {}\n",
            expected_include_path(&tree)
        ),
    )
    .unwrap();

    let output = cloakroom(&tree, &repo, &["status"]);
    assert_eq!(code(&output), 0, "stderr: {}", stderr(&output));
    assert!(
        stdout(&output).contains("profile:    work (selected by cloakroom)"),
        "stdout: {}",
        stdout(&output)
    );

    let output = cloakroom(&tree, &repo, &["doctor"]);
    assert_eq!(
        code(&output),
        0,
        "stdout: {}\nstderr: {}",
        stdout(&output),
        stderr(&output)
    );
}

/// The same file under two names. Init must see the symlinked include as the
/// one it would add and leave the gitconfig alone, and doctor must count the
/// two spellings as two includes of one root once both are present. Unix
/// only, for the symlink.
#[cfg(unix)]
#[test]
fn equivalent_include_targets_are_not_duplicated() {
    use std::os::unix::fs::symlink;

    let tree = TempTree::new("equivalent-include");
    tree.write_config(SAMPLE_ALL_USED);
    cloakroom(&tree, &tree.home(), &["init"]);
    let root = tree.config_dir().join("generated/root.gitconfig");
    let link = tree.config_dir().join("generated/root-link.gitconfig");
    symlink(&root, &link).unwrap();
    git(
        &tree,
        &tree.home(),
        &["config", "--global", "--unset-all", "include.path"],
    );
    git(
        &tree,
        &tree.home(),
        &[
            "config",
            "--global",
            "--add",
            "include.path",
            link.to_str().unwrap(),
        ],
    );

    let output = cloakroom(&tree, &tree.home(), &["init"]);
    assert_eq!(code(&output), 0, "stderr: {}", stderr(&output));
    assert_eq!(global_include_paths(&tree), [link.display().to_string()]);

    git(
        &tree,
        &tree.home(),
        &[
            "config",
            "--global",
            "--add",
            "include.path",
            &expected_include_path(&tree),
        ],
    );
    let output = cloakroom(&tree, &tree.home(), &["doctor"]);
    assert_eq!(code(&output), 1, "stdout: {}", stdout(&output));
    assert!(stdout(&output).contains("includes the generated root 2 times"));
}
